// src/pages/OrderItemsPage.tsx — generated by fabric-backend: the 20 latest rows of dbo.order_items, newest __timestamp first,
// through the connector 'shop'. Show it from src/App.tsx: `return <OrderItemsPage />;`
import { useEffect, useState } from 'react';

import type { OrderItems } from '../../rayfin/connectors/shop/schema';
import { getConnectorsClient } from '../lib/connectors';

const COLUMNS = ['orderId', 'lineNo', 'productId', 'quantity', 'timestamp'] as const;
const ROWS = 20;

type Row = Pick<OrderItems, (typeof COLUMNS)[number]>;

function cell(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (value instanceof Date) return value.toISOString();
  return String(value);
}

export function OrderItemsPage() {
  const [rows, setRows] = useState<Row[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    getConnectorsClient()
      .then((client) =>
        client.connectors.shop.OrderItems
          .select([...COLUMNS])
          .orderBy({ timestamp: 'desc' })
          .first(ROWS)
          .execute(),
      )
      .then((result) => {
        if (!cancelled) setRows(result);
      })
      .catch((e: unknown) => {
        if (!cancelled) setError(e instanceof Error ? e.message : String(e));
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <main className="p-6">
      <h1 className="mb-4 text-xl font-semibold">order_items: latest 20 rows</h1>
      {error && <p role="alert">Could not read the rows: {error}</p>}
      {!error && rows === null && <p>Loading…</p>}
      {rows && (
        <table className="text-left text-sm">
          <thead>
            <tr>
              {COLUMNS.map((c) => (
                <th key={c} className="px-2 py-1">
                  {c}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, i) => (
              <tr key={i}>
                {COLUMNS.map((c) => (
                  <td key={c} className="px-2 py-1">
                    {cell(row[c])}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </main>
  );
}

export default OrderItemsPage;
